/* =========================================================
   LofiStack Component Gallery — shared shell
   Nav, footer, homepage. Every class is prefixed `lsg-` so it
   never touches the components' own styles.
   ========================================================= */
:root {
  color-scheme: light;
  --lsg-bg: #EEF0F3;
  --lsg-surface: #FFFFFF;
  --lsg-ink: #11161D;
  --lsg-muted: #59626F;
  --lsg-faint: #89919D;
  --lsg-line: #D9DDE4;
  --lsg-hover: rgba(110, 122, 138, 0.12);
  --lsg-accent: #2446D8;
  --lsg-nav-bg: rgba(248, 249, 251, 0.8);
  --lsg-shadow: rgba(17, 22, 29, 0.2);
  --lsg-sans: "Segoe UI Variable Text", "Segoe UI", -apple-system, BlinkMacSystemFont, system-ui, "Helvetica Neue", Arial, sans-serif;
  --lsg-display: "Segoe UI Variable Display", "Segoe UI", -apple-system, BlinkMacSystemFont, system-ui, "Helvetica Neue", Arial, sans-serif;
  --lsg-mono: ui-monospace, "Cascadia Code", "SF Mono", Menlo, Consolas, monospace;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --lsg-bg: #0B0E13; --lsg-surface: #141920; --lsg-ink: #E7EBF0; --lsg-muted: #98A1AE;
    --lsg-faint: #6B7481; --lsg-line: #242A33; --lsg-hover: rgba(160, 170, 185, 0.1);
    --lsg-accent: #8FA3FF; --lsg-nav-bg: rgba(12, 15, 20, 0.78); --lsg-shadow: rgba(0, 0, 0, 0.6);
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --lsg-bg: #0B0E13; --lsg-surface: #141920; --lsg-ink: #E7EBF0; --lsg-muted: #98A1AE;
  --lsg-faint: #6B7481; --lsg-line: #242A33; --lsg-hover: rgba(160, 170, 185, 0.1);
  --lsg-accent: #8FA3FF; --lsg-nav-bg: rgba(12, 15, 20, 0.78); --lsg-shadow: rgba(0, 0, 0, 0.6);
}

/* base reset shared by every page */
body { margin: 0; }
img { max-width: 100%; }
[hidden] { display: none !important; }

/* ---------- top navigation ---------- */
.lsg-nav {
  position: sticky; top: 0; z-index: 50;
  padding-top: env(safe-area-inset-top, 0px);
  background: var(--lsg-nav-bg);
  -webkit-backdrop-filter: saturate(1.4) blur(14px);
          backdrop-filter: saturate(1.4) blur(14px);
  border-bottom: 1px solid var(--lsg-line);
  font-family: var(--lsg-sans);
}
.lsg-nav-inner {
  max-width: 1080px; margin: 0 auto;
  padding-inline: 20px; min-height: 58px;
  display: flex; align-items: center; justify-content: space-between; gap: 6px 20px;
  flex-wrap: wrap;
}
.lsg-brand {
  display: inline-flex; align-items: center; gap: 10px;
  color: var(--lsg-ink); text-decoration: none;
  font: 650 15px/1 var(--lsg-display); letter-spacing: -0.01em;
  padding-block: 8px; border-radius: 8px;
}
.lsg-brand small { font: 500 10.5px/1 var(--lsg-mono); letter-spacing: .09em; text-transform: uppercase; color: var(--lsg-faint); }
.lsg-logo { width: 22px; height: 22px; flex: none; color: var(--lsg-ink); transition: transform .5s cubic-bezier(.2,.7,.2,1); }
.lsg-brand:hover .lsg-logo { transform: translateY(-1px) rotate(-6deg); }
.lsg-links { position: relative; display: flex; gap: 2px; overflow-x: auto; scrollbar-width: none; max-width: 100%; overscroll-behavior-x: contain; }
.lsg-links::-webkit-scrollbar { display: none; }
/* fade whichever edge has more links behind it (classes set by gallery-nav.js) */
.lsg-links.is-scrollable { -webkit-mask-image: linear-gradient(to right, transparent, #000 28px, #000 calc(100% - 28px), transparent); mask-image: linear-gradient(to right, transparent, #000 28px, #000 calc(100% - 28px), transparent); }
.lsg-links.is-scrollable.is-start { -webkit-mask-image: linear-gradient(to right, #000 calc(100% - 28px), transparent); mask-image: linear-gradient(to right, #000 calc(100% - 28px), transparent); }
.lsg-links.is-scrollable.is-end { -webkit-mask-image: linear-gradient(to right, transparent, #000 28px); mask-image: linear-gradient(to right, transparent, #000 28px); }
.lsg-links.is-scrollable.is-start.is-end { -webkit-mask-image: none; mask-image: none; }
.lsg-links a {
  display: inline-flex; align-items: center; gap: 7px; white-space: nowrap;
  padding: 8px 10px; border-radius: 7px;
  color: var(--lsg-muted); text-decoration: none;
  font: 500 13px/1 var(--lsg-sans);
  transition: background .2s, color .2s;
}
.lsg-links a span { font: 500 10.5px/1 var(--lsg-mono); color: var(--lsg-faint); }
.lsg-links a:hover { color: var(--lsg-ink); background: var(--lsg-hover); }
.lsg-links a[aria-current="page"] { color: var(--lsg-ink); background: var(--lsg-surface); box-shadow: 0 0 0 1px var(--lsg-line); }
.lsg-nav a:focus-visible, .lsg-footer a:focus-visible, .lsg-home a:focus-visible { outline: 2px solid var(--lsg-accent); outline-offset: 2px; }
@media (max-width: 640px) {
  .lsg-nav-inner { padding-block: 6px; }
  .lsg-links { width: 100%; margin-inline: -10px; padding-bottom: 4px; }
}

/* ---------- component-page footer (prev / next) ---------- */
.lsg-footer { border-top: 1px solid var(--lsg-line); font-family: var(--lsg-sans); color: var(--lsg-muted); }
.lsg-footer-inner {
  max-width: 1080px; margin: 0 auto;
  padding: 28px 20px calc(40px + env(safe-area-inset-bottom, 0px));
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px;
}
.lsg-pager {
  display: grid; gap: 7px; padding: 16px 18px;
  background: var(--lsg-surface); border: 1px solid var(--lsg-line); border-radius: 12px;
  color: var(--lsg-ink); text-decoration: none;
  transition: transform .35s cubic-bezier(.2,.7,.2,1), border-color .25s, box-shadow .35s;
}
.lsg-pager:hover { transform: translateY(-2px); border-color: var(--lsg-faint); box-shadow: 0 18px 32px -26px var(--lsg-shadow); }
.lsg-pager--next { text-align: right; }
.lsg-pager small { font: 500 10.5px/1 var(--lsg-mono); letter-spacing: .09em; text-transform: uppercase; color: var(--lsg-faint); }
.lsg-pager strong { font: 600 15px/1.25 var(--lsg-display); }
.lsg-foot-note { grid-column: 1 / -1; display: flex; justify-content: space-between; gap: 8px 16px; flex-wrap: wrap; font-size: 12.5px; color: var(--lsg-faint); padding-top: 10px; }
.lsg-foot-note a { color: var(--lsg-muted); }
@media (max-width: 560px) {
  .lsg-footer-inner { grid-template-columns: 1fr; }
  .lsg-pager--next { text-align: left; }
}

/* ---------- embed mode (homepage previews load pages with ?embed) ---------- */
html.lsg-embed .lsg-nav,
html.lsg-embed .lsg-footer,
html.lsg-embed .intro,
html.lsg-embed .docs,
html.lsg-embed .stage-bar { display: none !important; }
html.lsg-embed .shell { max-width: none; padding: 28px; }
html.lsg-embed body { overflow: hidden; }

/* ---------- homepage ---------- */
body.lsg-page {
  background: var(--lsg-bg);
  color: var(--lsg-ink);
  font: 400 15px/1.55 var(--lsg-sans);
}
.lsg-home { max-width: 1080px; margin: 0 auto; padding: 60px 20px 72px; display: grid; gap: 48px; }

.lsg-hero { display: grid; gap: 18px; }
.lsg-kicker { font: 500 11px/1 var(--lsg-mono); letter-spacing: .1em; text-transform: uppercase; color: var(--lsg-faint); display: flex; gap: 10px; flex-wrap: wrap; }
.lsg-hero h1 {
  margin: 0; max-width: 15ch;
  font: 600 clamp(38px, 6.4vw, 68px)/1.0 var(--lsg-display);
  letter-spacing: -0.038em; text-wrap: balance;
}
.lsg-hero h1 em { font-style: normal; color: var(--lsg-faint); }
.lsg-hero p { margin: 0; max-width: 58ch; font-size: 16.5px; color: var(--lsg-muted); }
.lsg-facts { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0 0; padding: 0; list-style: none; }
.lsg-facts li {
  font: 500 12px/1 var(--lsg-mono); color: var(--lsg-muted);
  padding: 8px 11px; border: 1px solid var(--lsg-line); border-radius: 999px; background: var(--lsg-surface);
}
.lsg-facts b { color: var(--lsg-ink); font-weight: 600; }

.lsg-section-head { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; border-bottom: 1px solid var(--lsg-line); padding-bottom: 12px; }
.lsg-section-head h2 { margin: 0; font: 600 13px/1 var(--lsg-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--lsg-muted); }
.lsg-section-head span { font: 500 12px/1 var(--lsg-mono); color: var(--lsg-faint); }

.lsg-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }
@media (max-width: 780px) { .lsg-grid { grid-template-columns: 1fr; } }

.lsg-card {
  position: relative; display: grid;
  background: var(--lsg-surface);
  border: 1px solid var(--lsg-line); border-radius: 16px; overflow: hidden;
  transition: transform .45s cubic-bezier(.2,.7,.2,1), box-shadow .45s ease, border-color .3s;
}
.lsg-card:hover { transform: translateY(-4px); border-color: var(--lsg-faint); box-shadow: 0 34px 56px -40px var(--lsg-shadow); }
.lsg-preview {
  position: relative; aspect-ratio: 16 / 10; max-width: 100%; overflow: hidden;
  background: var(--lsg-bg); border-bottom: 1px solid var(--lsg-line);
}
.lsg-preview iframe {
  position: absolute; top: 0; left: 0;
  width: 1200px; height: 750px; border: 0;
  transform-origin: 0 0; transform: scale(var(--s, 0.4));
  pointer-events: none;
  transition: transform .8s cubic-bezier(.2,.7,.2,1);
}
.lsg-card:hover .lsg-preview iframe { transform: scale(calc(var(--s, 0.4) * 1.025)); }
.lsg-preview::after {
  content: ""; position: absolute; inset: auto 0 0 0; height: 28%;
  background: linear-gradient(to bottom, transparent, var(--lsg-bg));
  pointer-events: none;
}
.lsg-card-body { padding: 20px 22px 22px; display: grid; gap: 10px; }
.lsg-card-top { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; font: 500 11.5px/1 var(--lsg-mono); color: var(--lsg-faint); }
.lsg-card-top b { color: var(--lsg-muted); font-weight: 500; letter-spacing: .06em; }
.lsg-card h3 { margin: 0; font: 600 21px/1.2 var(--lsg-display); letter-spacing: -0.015em; }
.lsg-card-link { color: inherit; text-decoration: none; }
.lsg-card-link::after { content: ""; position: absolute; inset: 0; border-radius: inherit; }
.lsg-card p { margin: 0; color: var(--lsg-muted); font-size: 14.5px; max-width: 52ch; }
.lsg-tags { display: flex; flex-wrap: wrap; gap: 6px; margin: 4px 0 0; padding: 0; list-style: none; }
.lsg-tags li { font: 400 11.5px/1 var(--lsg-mono); color: var(--lsg-muted); padding: 6px 9px; border-radius: 6px; background: var(--lsg-bg); }
.lsg-open { margin-top: 6px; display: inline-flex; align-items: center; gap: 8px; font: 600 13.5px/1 var(--lsg-sans); color: var(--lsg-accent); }
.lsg-open svg { width: 14px; height: 14px; transition: transform .35s cubic-bezier(.2,.7,.2,1); }
.lsg-card:hover .lsg-open svg { transform: translateX(4px); }

.lsg-home-foot { display: flex; justify-content: space-between; gap: 8px 16px; flex-wrap: wrap; border-top: 1px solid var(--lsg-line); padding-top: 18px; font-size: 12.5px; color: var(--lsg-faint); }

.lsg-404 { max-width: 640px; margin: 0 auto; padding: 96px 20px; display: grid; gap: 14px; }
.lsg-404 h1 { margin: 0; font: 600 clamp(32px, 6vw, 48px)/1.05 var(--lsg-display); letter-spacing: -0.03em; }
.lsg-404 p { margin: 0; color: var(--lsg-muted); }
.lsg-404 a { color: var(--lsg-accent); font-weight: 600; }

@media (prefers-reduced-motion: reduce) {
  .lsg-card, .lsg-pager, .lsg-preview iframe, .lsg-open svg, .lsg-logo { transition: none; }
  .lsg-card:hover, .lsg-pager:hover { transform: none; }
  .lsg-card:hover .lsg-preview iframe { transform: scale(var(--s, 0.4)); }
}

assets/agent-log-card.css:
/* =========================================================
   Agent Log Card — homepage copy
   Copied unchanged from components/agent-log-card/index.html
   (tokens + "Agent Log Card component" block) so the homepage
   can show real log entries. Keep the two in sync.
   ========================================================= */
:root {
  --alc-card: #FCFDFD;
  --alc-ink: #12171C;
  --alc-muted: #5A646E;
  --alc-faint: #8C96A0;
  --alc-line: #DCE2E6;
  --alc-panel: #F1F4F5;
  --alc-accent: #1E6B62;
  --alc-accent-soft: #DDEEEB;
  --alc-on-accent: #F4FBFA;
  --alc-glow: rgba(30, 107, 98, 0.09);
  --alc-shadow: rgba(18, 30, 38, 0.22);
  --alc-ground: var(--lsg-bg);            /* colour behind the card — used by the perforation notches */
  --alc-draft: #9A6511;      --alc-draft-bg: #F8EDD8;
  --alc-selected: #2B57C4;   --alc-selected-bg: #E2E9FA;
  --alc-submitted: #1D7A45;  --alc-submitted-bg: #DDF1E4;
  --alc-display: "Bricolage Grotesque", "Segoe UI", system-ui, sans-serif;
  --alc-body: "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
  --alc-mono: "IBM Plex Mono", ui-monospace, "Cascadia Mono", Consolas, monospace;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --alc-card: #181D21; --alc-ink: #E9EDF0; --alc-muted: #9CA6B0; --alc-faint: #6E7882;
    --alc-line: #2A3137; --alc-panel: #1F252A; --alc-accent: #5FC2B2; --alc-accent-soft: #1B3632;
    --alc-on-accent: #0B1A18; --alc-glow: rgba(95, 194, 178, 0.08); --alc-shadow: rgba(0, 0, 0, 0.6);
    --alc-draft: #E3B25E; --alc-draft-bg: #33280F;
    --alc-selected: #86A6F5; --alc-selected-bg: #1A2544;
    --alc-submitted: #6BD097; --alc-submitted-bg: #13301F;
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --alc-card: #181D21; --alc-ink: #E9EDF0; --alc-muted: #9CA6B0; --alc-faint: #6E7882;
  --alc-line: #2A3137; --alc-panel: #1F252A; --alc-accent: #5FC2B2; --alc-accent-soft: #1B3632;
  --alc-on-accent: #0B1A18; --alc-glow: rgba(95, 194, 178, 0.08); --alc-shadow: rgba(0, 0, 0, 0.6);
  --alc-draft: #E3B25E; --alc-draft-bg: #33280F;
  --alc-selected: #86A6F5; --alc-selected-bg: #1A2544;
  --alc-submitted: #6BD097; --alc-submitted-bg: #13301F;
}

agent-log-card {
  display: block;
  container-type: inline-size;
  width: 100%;
  max-width: 680px;
  font-family: var(--alc-body);
  color: var(--alc-ink);
}
.alc {
  --pad: 30px;
  position: relative;
  background: var(--alc-card);
  border: 1px solid var(--alc-line);
  border-radius: 20px;
  padding: calc(var(--pad) - 4px) var(--pad) var(--pad);
  box-shadow: 0 1px 0 rgba(255,255,255,0.5) inset, 0 22px 44px -30px var(--alc-shadow), 0 2px 6px -3px var(--alc-shadow);
  transition: transform .45s cubic-bezier(.2,.7,.2,1), box-shadow .45s ease;
  display: grid;
  gap: 22px;
}
.alc::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(460px circle at var(--mx, 70%) var(--my, -10%), var(--alc-glow), transparent 62%);
  opacity: 0;
  transition: opacity .5s ease;
  pointer-events: none;
}
.alc > * { position: relative; }
.alc:hover { transform: translateY(-3px); box-shadow: 0 1px 0 rgba(255,255,255,0.5) inset, 0 34px 60px -34px var(--alc-shadow), 0 4px 10px -5px var(--alc-shadow); }
.alc:hover::before { opacity: 1; }

/* top rail */
.alc-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.alc-eyebrow {
  font: 500 11px/1 var(--alc-mono);
  letter-spacing: .09em;
  text-transform: uppercase;
  color: var(--alc-faint);
  display: inline-flex; gap: 8px; align-items: center;
}
.alc-eyebrow b { font-weight: 500; color: var(--alc-muted); }
.alc-eyebrow i { font-style: normal; opacity: .6; }

.alc-status {
  --c: var(--alc-muted); --bg: var(--alc-panel);
  display: inline-flex; align-items: center; gap: 7px;
  padding: 6px 11px 6px 9px;
  border-radius: 999px;
  background: var(--bg);
  color: var(--c);
  font: 600 12px/1 var(--alc-body);
  letter-spacing: .01em;
}
.alc-status[data-state="draft"]     { --c: var(--alc-draft);     --bg: var(--alc-draft-bg); }
.alc-status[data-state="selected"]  { --c: var(--alc-selected);  --bg: var(--alc-selected-bg); }
.alc-status[data-state="submitted"] { --c: var(--alc-submitted); --bg: var(--alc-submitted-bg); }
.alc-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--c); position: relative; }
.alc-status[data-state="draft"] .alc-dot::after {
  content: ""; position: absolute; inset: -4px; border-radius: 50%;
  border: 1.5px solid var(--c); opacity: 0;
  animation: alc-ping 2.4s ease-out infinite;
}
.alc-status[data-state="submitted"] .alc-dot { width: 12px; height: 12px; display: grid; place-items: center; }
.alc-status[data-state="submitted"] .alc-dot::before {
  content: ""; width: 5px; height: 3px; margin-top: -1px;
  border: solid var(--bg); border-width: 0 0 1.6px 1.6px; transform: rotate(-45deg);
}
@keyframes alc-ping { 0% { transform: scale(.5); opacity: .7; } 80%, 100% { transform: scale(1.4); opacity: 0; } }

/* title */
.alc-task {
  margin: -4px 0 0;
  font: 650 clamp(22px, 5.2cqi, 30px)/1.12 var(--alc-display);
  letter-spacing: -0.018em;
  text-wrap: balance;
  color: var(--alc-ink);
}

/* meta strip */
.alc-meta {
  margin: 0;
  display: grid;
  grid-template-columns: 1.25fr 1fr 0.9fr;
  border-block: 1px solid var(--alc-line);
}
.alc-meta > div { padding: 13px 16px; min-width: 0; }
.alc-meta > div:first-child { padding-left: 0; }
.alc-meta > div + div { border-left: 1px solid var(--alc-line); }
.alc-meta dt {
  font: 500 10.5px/1 var(--alc-mono);
  letter-spacing: .09em; text-transform: uppercase;
  color: var(--alc-faint);
  margin-bottom: 8px;
}
.alc-meta dd { margin: 0; font: 500 14.5px/1.35 var(--alc-body); overflow-wrap: anywhere; }
.alc-agent { display: inline-flex; align-items: center; gap: 8px; }
.alc-agent::before {
  content: ""; flex: none; width: 8px; height: 8px; border-radius: 2px;
  background: var(--alc-accent);
  box-shadow: 0 0 0 3px var(--alc-accent-soft);
  transition: transform .5s cubic-bezier(.2,.7,.2,1);
}
.alc:hover .alc-agent::before { transform: rotate(45deg); }
.alc-date { font-variant-numeric: tabular-nums; }

/* input / output sections */
.alc-io { display: grid; gap: 12px; }
.alc-io-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 28px; }
.alc-io-label { display: inline-flex; align-items: center; gap: 10px; font: 600 13px/1 var(--alc-body); color: var(--alc-ink); }
.alc-tag {
  font: 500 10px/1 var(--alc-mono); letter-spacing: .1em;
  padding: 5px 7px 4px; border-radius: 6px;
  background: var(--alc-accent-soft); color: var(--alc-accent);
}
.alc-out .alc-tag { background: var(--alc-accent); color: var(--alc-on-accent); }

.alc-btn {
  appearance: none; border: 1px solid transparent; background: transparent;
  font: 500 12px/1 var(--alc-body); color: var(--alc-muted);
  padding: 7px 10px; border-radius: 8px; cursor: pointer;
  display: inline-flex; align-items: center; gap: 6px;
  transition: background .2s, color .2s, border-color .2s;
}
.alc-btn:hover { background: var(--alc-panel); color: var(--alc-ink); border-color: var(--alc-line); }
.alc-btn:focus-visible { outline: 2px solid var(--alc-accent); outline-offset: 2px; }
.alc-btn svg { width: 13px; height: 13px; }
.alc-btn[data-done] { color: var(--alc-accent); }

.alc-prompt {
  margin: 0;
  position: relative;
  background: var(--alc-panel);
  border-radius: 12px;
  padding: 14px 16px 14px 36px;
  font: 400 13px/1.65 var(--alc-mono);
  color: var(--alc-ink);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  max-height: calc(1.65em * 9 + 28px);
  overflow: hidden;
  transition: max-height .5s cubic-bezier(.2,.7,.2,1);
}
.alc-prompt::before {
  content: "›"; position: absolute; left: 16px; top: 13px;
  color: var(--alc-accent); font-weight: 500;
}
.alc--clamped .alc-prompt:not(.is-open) {
  -webkit-mask-image: linear-gradient(to bottom, #000 62%, transparent);
          mask-image: linear-gradient(to bottom, #000 62%, transparent);
}
.alc-expand { justify-self: start; margin-top: -4px; padding-left: 0; }
.alc-expand:hover { padding-left: 10px; }
.alc-expand svg { transition: transform .35s ease; }
.alc-expand[aria-expanded="true"] svg { transform: rotate(180deg); }

/* perforation between input and output */
.alc-tear {
  display: flex; align-items: center;
  margin-inline: calc(var(--pad) * -1 - 1px);
  height: 22px;
}
.alc-notch {
  flex: none; width: 12px; height: 22px;
  background: var(--alc-ground);
  border: 1px solid var(--alc-line);
}
.alc-notch--l { border-left: 0; border-radius: 0 22px 22px 0; }
.alc-notch--r { border-right: 0; border-radius: 22px 0 0 22px; }
.alc-perf {
  flex: 1; height: 2px; margin-inline: 10px;
  background-image: linear-gradient(to right, var(--alc-line) 55%, transparent 0);
  background-size: 9px 2px;
  transition: background-position 1.2s cubic-bezier(.2,.7,.2,1);
}
.alc:hover .alc-perf { background-position: 36px 0; }

/* result */
.alc-result { font: 400 15px/1.62 var(--alc-body); color: var(--alc-ink); max-width: 64ch; }
.alc-result > * { margin: 0; }
.alc-result > * + * { margin-top: 12px; }
.alc-result ul { padding: 0; list-style: none; display: grid; gap: 6px; }
.alc-result li { padding-left: 18px; position: relative; color: var(--alc-muted); }
.alc-result li::before { content: ""; position: absolute; left: 2px; top: .8em; width: 8px; height: 1.5px; background: var(--alc-accent); }
.alc-result code { font: 400 .88em var(--alc-mono); background: var(--alc-panel); padding: 1px 5px; border-radius: 5px; }
.alc-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.alc-chip {
  font: 400 12px/1 var(--alc-mono); color: var(--alc-muted);
  padding: 7px 10px; border: 1px solid var(--alc-line); border-radius: 999px;
  transition: border-color .2s, color .2s, transform .2s;
}
.alc-chip:hover { border-color: var(--alc-accent); color: var(--alc-accent); transform: translateY(-1px); }

/* narrow: stack meta, tighten padding */
@container (max-width: 540px) {
  .alc { --pad: 20px; border-radius: 18px; gap: 18px; }
  .alc-meta { grid-template-columns: 1fr; }
  .alc-meta > div, .alc-meta > div:first-child {
    padding: 11px 0; display: flex; justify-content: space-between; align-items: baseline; gap: 16px;
  }
  .alc-meta > div + div { border-left: 0; border-top: 1px solid var(--alc-line); }
  .alc-meta dt { margin: 0; }
  .alc-meta dd { text-align: right; }
  .alc-prompt { font-size: 12.5px; padding-left: 30px; }
  .alc-prompt::before { left: 13px; }
}

@media (prefers-reduced-motion: reduce) {
  .alc, .alc::before, .alc-perf, .alc-prompt, .alc-agent::before, .alc-chip { transition: none; }
  .alc:hover { transform: none; }
  .alc-status .alc-dot::after { animation: none; }
}

